begin;
create extension if not exists pgtap with schema extensions;
select plan(23);
insert into public.agent_keys(id,company_id,person_id,key_hash) values ('a0000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','test-hash');
select is((select count(*)::int from public.lookup_agent_key('test-hash')),1,'active contributor key resolves');
update public.agent_keys set revoked_at=now() where id='a0000000-0000-0000-0000-000000000001';
select is((select count(*)::int from public.lookup_agent_key('test-hash')),0,'revoked key does not resolve');
update public.agent_keys set revoked_at=null where id='a0000000-0000-0000-0000-000000000001';
insert into public.work_cards(company_id,stage_id,title) select company_id,id,'Company B private card' from public.work_stages where company_id='10000000-0000-0000-0000-000000000002' and position=1;
select set_config('test.company_b_card',(select id::text from public.work_cards where company_id='10000000-0000-0000-0000-000000000002' and title='Company B private card'),true);
insert into public.agent_webhooks(company_id,url,secret_encrypted) values ('10000000-0000-0000-0000-000000000001','http://localhost/test','fixture');
select is((select count(*)::int from generate_series(1,120) where public.agent_rate_limit('a0000000-0000-0000-0000-000000000001')),0,'first 120 requests allowed');
select is(public.agent_rate_limit('a0000000-0000-0000-0000-000000000001'),true,'request 121 limited');
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select is((select count(*)::int from public.work_cards where company_id='10000000-0000-0000-0000-000000000002'),0,'company B cards are hidden');
select is((select count(*)::int from public.work_stages where company_id='10000000-0000-0000-0000-000000000002'),0,'company B stages are hidden');
select is((select count(*)::int from public.work_activity where company_id='10000000-0000-0000-0000-000000000002'),0,'company B activity is hidden');
select throws_ok($$select public.agent_write('10000000-0000-0000-0000-000000000002','k','fingerprint','create',null,'{"stage":1,"title":"Denied"}')$$,null,null,'agent cannot create for another company');
select throws_ok($$select public.agent_write('10000000-0000-0000-0000-000000000002','k2','fingerprint','edit',current_setting('test.company_b_card')::bigint,'{"fields":{"title":"Changed"}}')$$,null,null,'agent cannot edit another company');
select throws_ok($$select public.agent_write('10000000-0000-0000-0000-000000000001','k','fingerprint','move',1,jsonb_build_object('stage',(select id from public.work_stages where company_id='10000000-0000-0000-0000-000000000001' and kind='after_review' limit 1)))$$,'P0001','contributors cannot move beyond review','agent cannot move beyond review');
select throws_ok($$select public.decide_approval('10000000-0000-0000-0000-000000000001',1,'approve')$$,null,null,'contributor cannot approve');
select lives_ok($$select public.agent_write('10000000-0000-0000-0000-000000000001','retry-key','same','create',null,jsonb_build_object('stage',(select id from public.work_stages where company_id='10000000-0000-0000-0000-000000000001' and kind='before_review' limit 1),'title','Idempotent'))$$,'create through API function');
select lives_ok($$select public.agent_write('10000000-0000-0000-0000-000000000001','retry-key','same','create',null,'{}')$$,'retry returns stored result');
select is((select count(*)::int from public.work_cards where company_id='10000000-0000-0000-0000-000000000001' and title='Idempotent'),1,'retry creates one card');
with changed as (update public.agent_requests set result='{}' where request_key='retry-key' returning 1) select is(count(*)::int,0,'agent cannot rewrite idempotency result') from changed;
with removed as (delete from public.agent_requests where request_key='retry-key' returning 1) select is(count(*)::int,0,'agent cannot delete idempotency result') from removed;
select lives_ok($$select public.change_work_card('10000000-0000-0000-0000-000000000001',1,'comment','{"body":"agent comment"}')$$,'agent comments');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.change_work_card('10000000-0000-0000-0000-000000000001',1,'comment','{"body":"human comment"}')$$,'person comments');
select is((select count(*)::int from public.webhook_deliveries where event->>'event_type'='commented' and event->>'comment'='human comment'),1,'person comment enqueued');
select is((select count(*)::int from public.webhook_deliveries where event->>'comment'='agent comment'),0,'agent comment not enqueued');
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.log_agent_refusal('10000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000001','/denied')$$,'agent refusal is recorded');
reset role;
select is((select count(*)::int from public.agent_refusals where path='/denied'),1,'refusal survives');
select ok(not has_function_privilege('authenticated','public.lookup_agent_key(text)','execute'),'lookup is restricted');
select * from finish();
rollback;
